INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (317892, 14073, 'Euronews', 'en', 'Timelapse of partial solar eclipse seen from Royal Observatory Greenwich', 'http://www.euronews.com/video/2026/08/13/timelapse-of-partial-solar-eclipse-seen-from-royal-observatory-greenwich', 'Britain witnessed its most significant solar eclipse since 1999, with more than 90% of the Sun obscured in some parts of the country. Crowds gathered in parks and open spaces to watch the rare celestial event. In London, the sky turned an eerie grey as a sliver of sunlight appeared above the Moon.', '', '2026-08-13T07:47:42+00:00', '2026-08-13T08:28:42.149724'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (317897, 14073, 'Euronews', 'en', 'Half a million visitors flock to Spain’s path of total solar eclipse', 'http://www.euronews.com/video/2026/08/13/half-a-million-visitors-flock-to-spains-path-of-total-solar-eclipse', 'Spain witnessed its first total solar eclipse in more than a century on Wednesday 12 August, drawing millions of people to viewing sites across the north of the country as the Moon passed directly in front of the Sun.', '', '2026-08-13T06:28:57+00:00', '2026-08-13T08:28:42.396680'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
