INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (316434, 14074, 'Aaj Tak', 'hi', 'कौन हैं हसन महमूद? ज‍िन्होंने 6 व‍िकेट लेकर कंगारुओं को रेल डाला', 'https://www.aajtak.in/sports/cricket/story/who-is-hasan-mahmud-bangladesh-fast-bowler-6-wickets-vs-australia-1st-test-darwin-tspok-dskc-2621138-2026-08-13', 'इस समय बांग्लादेश की टीम ऑस्ट्रेल‍िया के दौरे पर है, दोनों देशों के बीच 2 टेस्ट मैचों की सीरीज हो रही है. पहला टेस्ट डार्व‍िन में शुरू हुआ, जहां बांग्लादेशी गेंदबाज हसन महमूद ने 6 व‍िकेट झटकर ऑस्ट्रेल‍िया की हवा न‍िकाल दी.', '', '2026-08-13T06:38:52+00:00', '2026-08-13T07:07:48.243614'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
