INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (317347, 14074, 'Aaj Tak', 'hi', 'बांग्लादेश ऐसा करेगा! ऑस्ट्रेल‍िया ने सोचा ना होगा, बना शर्मनाक र‍िकॉर्ड', 'https://www.aajtak.in/sports/cricket/story/bangladesh-bowl-out-australia-under-200-first-time-aus-vs-ban-darwin-test-tspok-dskc-2621175-2026-08-13', 'ऑस्ट्रेलिया के खिलाफ टेस्ट क्रिकेट में बांग्लादेश ने पहली बार उसे 200 रन से पहले ऑलआउट कर दिया. डार्विन टेस्ट के पहले दिन (13 ) ऑस्ट्रेलिया 53 ओवर में 198 रन पर सिमट गया. हसन महमूद ने छह विकेट लेकर इतिहास रचा. स्टीव स्मिथ ने 71 रन बनाकर अकेले संघर्ष किया, लेकिन दूसरी तरफ लगातार विकेट गिरते रहे और ऑस्ट्रेलियाई पारी ढह गई.', '', '2026-08-13T07:41:12+00:00', '2026-08-13T08:12:38.838181'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (317370, 14074, 'Aaj Tak', 'hi', 'राजकुमारी मत बनो... लाइव मैच में कंगारू बल्लेबाज हुआ ट्रोल', 'https://www.aajtak.in/sports/cricket/story/fan-trolls-steve-smith-over-sight-screen-issue-australia-bangladesh-test-tspoa-dskc-2621157-2026-08-13', 'डार्विन टेस्ट मैच में ऑस्ट्रेलियाई टीम पहली पारी में 198 रन ही बना सकी. मुकाबले के पहले दिन जहां मेजबान टीम के बाकी बल्लेबाज बांग्लादेशी पेस अटैक के सामने टिक नहीं सके, वहीं स्टीव स्मिथ ने संयम दिखाते हुए ऑस्ट्रेलियाई टीम को पूरी तरह ढहने से बचाया.', '', '2026-08-13T07:18:37+00:00', '2026-08-13T08:12:40.482318'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
